8: /// How a ray scatters off a surface.
9: pub trait Material {
10:     /// Return the attenuation and the scattered ray, or `None` when the ray is absorbed.
11:     fn scatter(&self, ray: &Ray, hit: &HitRecord, rng: &mut Rng) -> Option<(Colour, Ray)>;
12: }
