14: /// A diffuse surface that scatters in a random direction around the normal.
15: pub struct Lambertian {
16:     pub albedo: Colour,
17: }
18: 
19: impl Lambertian {
20:     /// A diffuse material that attenuates by `albedo`.
21:     pub fn new(albedo: Colour) -> Self {
22:         Lambertian { albedo }
23:     }
24: }
