26: impl Material for Lambertian {
27:     fn scatter(&self, _ray: &Ray, hit: &HitRecord, rng: &mut Rng) -> Option<(Colour, Ray)> {
28:         Some((
29:             self.albedo,
30:             Ray::new(hit.point, hit.normal + random_unit_vector(rng)),
31:         ))
32:     }
33: }
