35: /// A metal surface that reflects about the normal, blurred by `fuzz`.
36: pub struct Metal {
37:     pub albedo: Colour,
38:     pub fuzz: f64,
39: }
40: 
41: impl Metal {
42:     /// A metal material that attenuates by `albedo` and blurs its reflection by `fuzz` in `0.0..=1.0`.
43:     pub fn new(albedo: Colour, fuzz: f64) -> Self {
44:         Metal { albedo, fuzz }
45:     }
46: }
47: 
48: impl Material for Metal {
49:     fn scatter(&self, ray: &Ray, hit: &HitRecord, rng: &mut Rng) -> Option<(Colour, Ray)> {
50:         let reflected = reflect(ray.direction.unit(), hit.normal);
51:         let scattered = Ray::new(hit.point, reflected + random_unit_vector(rng) * self.fuzz);
52:         if scattered.direction.dot(hit.normal) <= 0.0 {
53:             return None;
54:         }
55:         Some((self.albedo, scattered))
56:     }
57: }
58: 
59: /// A transparent material that refracts by its refractive index.
60: pub struct Dielectric {
61:     pub refractive_index: f64,
62: }
63: 
64: impl Dielectric {
65:     /// A transparent material with refractive index `refractive_index`.
66:     pub fn new(refractive_index: f64) -> Self {
67:         Dielectric { refractive_index }
68:     }
69: }
70: 
71: impl Material for Dielectric {
72:     fn scatter(&self, ray: &Ray, hit: &HitRecord, rng: &mut Rng) -> Option<(Colour, Ray)> {
73:         let front_face = ray.direction.dot(hit.normal) < 0.0;
74:         let normal = if front_face { hit.normal } else { -hit.normal };
75:         let ratio = if front_face {
76:             1.0 / self.refractive_index
77:         } else {
78:             self.refractive_index
79:         };
80:         let unit_direction = ray.direction.unit();
81:         let cos_theta = (-unit_direction.dot(normal)).min(1.0);
82:         let sin_theta = (1.0 - cos_theta * cos_theta).sqrt();
83:         let direction = if ratio * sin_theta > 1.0 || schlick(cos_theta, ratio) > rng.next_f64() {
84:             reflect(unit_direction, normal)
85:         } else {
86:             refract(unit_direction, normal, ratio)
87:         };
88:         Some((Colour::new(1.0, 1.0, 1.0), Ray::new(hit.point, direction)))
89:     }
90: }
91: 
92: fn reflect(direction: Vec3, normal: Vec3) -> Vec3 {
93:     direction - normal * (2.0 * direction.dot(normal))
94: }
95: 
96: fn refract(direction: Vec3, normal: Vec3, ratio: f64) -> Vec3 {
97:     let cos_theta = (-direction).dot(normal).min(1.0);
98:     let perpendicular = (direction + normal * cos_theta) * ratio;
99:     let parallel = normal * -(1.0 - perpendicular.dot(perpendicular)).max(0.0).sqrt();
100:     perpendicular + parallel
101: }
102: 
103: fn schlick(cosine: f64, ratio: f64) -> f64 {
104:     let r0 = (1.0 - ratio) / (1.0 + ratio);
105:     let r0 = r0 * r0;
106:     r0 + (1.0 - r0) * (1.0 - cosine).powi(5)
107: }
108: 
109: fn random_unit_vector(rng: &mut Rng) -> Vec3 {
110:     loop {
111:         let candidate = Vec3::new(
112:             2.0 * rng.next_f64() - 1.0,
113:             2.0 * rng.next_f64() - 1.0,
114:             2.0 * rng.next_f64() - 1.0,
115:         );
116:         if candidate.length() < 1.0 {
117:             return candidate.unit();
118:         }
119:     }
120: }
