126: impl Config {
127:     /// Parse the command-line options, rejecting an unknown option, a missing value and a value
128:     /// the option cannot take, including an output path whose extension names no format when
129:     /// `--format` is absent.
130:     fn parse(args: impl Iterator<Item = String>) -> Result<Config, String> {
131:         let mut config = Config::default();
132:         let mut explicit_format: Option<Format> = None;
133:         let mut args = args;
134:         while let Some(arg) = args.next() {
135:             match arg.as_str() {
136:                 "--width" => config.width = parse_number(args.next(), "--width")?,
137:                 "--height" => config.height = parse_number(args.next(), "--height")?,
138:                 "--samples" => config.samples = parse_number(args.next(), "--samples")?,
139:                 "--output" => config.output = parse_value(args.next(), "--output")?,
140:                 "--format" => {
141:                     explicit_format = Some(match args.next().as_deref() {
142:                         Some("png") => Format::Png,
143:                         Some("ppm") => Format::Ppm,
144:                         _ => return Err("--format takes png or ppm".to_string()),
145:                     });
146:                 }
147:                 other => return Err(format!("unknown option: {other}")),
148:             }
149:         }
150:         if config.width < 2 {
151:             return Err("--width must be at least 2".to_string());
152:         }
153:         if config.height < 2 {
154:             return Err("--height must be at least 2".to_string());
155:         }
156:         if config.samples < 1 {
157:             return Err("--samples must be at least 1".to_string());
158:         }
159:         config.format = match explicit_format {
160:             Some(format) => format,
161:             None => match Path::new(&config.output)
162:                 .extension()
163:                 .and_then(|e| e.to_str())
164:             {
165:                 Some("png") => Format::Png,
166:                 Some("ppm") => Format::Ppm,
167:                 _ => return Err("--output must end in .png or .ppm".to_string()),
168:             },
169:         };
170:         Ok(config)
171:     }
172: }
