30:         let root = discriminant.sqrt();
31:         let mut t = (-half_b - root) / a;
32:         if t <= t_min || t >= t_max {
33:             t = (-half_b + root) / a;
34:             if t <= t_min || t >= t_max {
35:                 return None;
36:             }
37:         }
38:         let point = ray.at(t);
39:         let outward_normal = (point - self.center) / self.radius;
40:         let u = 0.5 + outward_normal.z.atan2(outward_normal.x) / (2.0 * PI);
41:         let v = 0.5 - outward_normal.y.asin() / PI;
42:         Some(HitRecord::new(t, point, u, v, ray, outward_normal))
43:     }
