28:         let determinant = edge1.dot(pvec);
29:         // A determinant near zero means the ray runs parallel to the triangle's plane.
30:         if determinant.abs() < 1e-8 {
31:             return None;
32:         }
33:         let inverse = 1.0 / determinant;
34:         let tvec = ray.origin - self.a;
35:         let u = tvec.dot(pvec) * inverse;
36:         if !(0.0..=1.0).contains(&u) {
