import struct, sys, zlib

def read_ppm(path):
    with open(path, 'rb') as f:
        tokens = []
        while len(tokens) < 4:
            line = f.readline().decode('ascii')
            if line.startswith('#'):
                continue
            tokens.extend(line.split())
        assert tokens[0] == 'P3', tokens[0]
        w, h, maxv = int(tokens[1]), int(tokens[2]), int(tokens[3])
        values = []
        for line in f.read().decode('ascii').split():
            values.append(int(line))
    assert maxv == 255 and len(values) == w * h * 3, (maxv, len(values), w * h * 3)
    return w, h, bytes(values)

def chunk(tag, data):
    return struct.pack('>I', len(data)) + tag + data + struct.pack('>I', zlib.crc32(tag + data) & 0xffffffff)

def write_png(path, w, h, rgb):
    raw = b''.join(b'\x00' + rgb[y*w*3:(y+1)*w*3] for y in range(h))
    png = b'\x89PNG\r\n\x1a\n'
    png += chunk(b'IHDR', struct.pack('>IIBBBBB', w, h, 8, 2, 0, 0, 0))
    png += chunk(b'IDAT', zlib.compress(raw, 9))
    png += chunk(b'IEND', b'')
    with open(path, 'wb') as f:
        f.write(png)

if __name__ == '__main__':
    w, h, rgb = read_ppm(sys.argv[1])
    write_png(sys.argv[2], w, h, rgb)
    print(f'{w}x{h} -> {sys.argv[2]}')

