37: /// The colour seen along a ray after its bounces, with the sky gradient on a miss.
38: fn ray_colour(ray: Ray, world: &dyn Hittable, rng: &mut Rng) -> Colour {
39:     let mut attenuation = Colour::new(1.0, 1.0, 1.0);
40:     let mut ray = ray;
41:     for _ in 0..MAX_BOUNCES {
42:         if let Some(hit) = world.hit(&ray, 0.001, f64::INFINITY) {
43:             match hit.material.scatter(&ray, &hit, rng) {
44:                 Some((factor, scattered)) => {
45:                     attenuation = attenuation * factor;
46:                     ray = scattered;
47:                 }
48:                 None => return Colour::new(0.0, 0.0, 0.0),
49:             }
50:         } else {
51:             let t = 0.5 * (ray.direction.unit().y + 1.0);
52:             let sky = Vec3::new(1.0, 1.0, 1.0) * (1.0 - t) + Vec3::new(0.5, 0.7, 1.0) * t;
53:             return attenuation * sky;
54:         }
55:     }
56:     Colour::new(0.0, 0.0, 0.0)
57: }
