1: //! Encode an image as a PNG file.
2: 
3: use std::io::{self, Write};
4: 
5: const SIGNATURE: [u8; 8] = [0x89, b'P', b'N', b'G', 0x0d, 0x0a, 0x1a, 0x0a];
6: const MAX_STORED_BLOCK: usize = 65535;
7: 
8: /// Write `rgb` as an 8-bit RGB PNG with no interlacing.
9: ///
10: /// `rgb` holds `width * height * 3` bytes, three per pixel, row by row from the top.
11: pub fn write_png(out: &mut impl Write, width: usize, height: usize, rgb: &[u8]) -> io::Result<()> {
12:     out.write_all(&SIGNATURE)?;
13: 
14:     let mut ihdr = [0u8; 13];
15:     ihdr[0..4].copy_from_slice(&(width as u32).to_be_bytes());
16:     ihdr[4..8].copy_from_slice(&(height as u32).to_be_bytes());
17:     ihdr[8] = 8;
18:     ihdr[9] = 2;
19:     write_chunk(out, b"IHDR", &ihdr)?;
20:     write_chunk(out, b"IDAT", &zlib_stream(&scanlines(width, height, rgb)))?;
21:     write_chunk(out, b"IEND", &[])
22: }
23: 
24: /// Write one chunk: the data length, the kind, the data and the CRC-32 of kind and data.
25: fn write_chunk(out: &mut impl Write, kind: &[u8; 4], data: &[u8]) -> io::Result<()> {
26:     out.write_all(&(data.len() as u32).to_be_bytes())?;
27:     out.write_all(kind)?;
28:     out.write_all(data)?;
29:     out.write_all(&crc32(&[kind, data]).to_be_bytes())
30: }
31: 
32: /// Prefix each row with filter byte 0 (no filter) to form the image's scanline stream.
33: fn scanlines(width: usize, height: usize, rgb: &[u8]) -> Vec<u8> {
34:     let mut raw = Vec::with_capacity(height * (width * 3 + 1));
35:     for row in rgb.chunks_exact(width * 3) {
36:         raw.push(0);
37:         raw.extend_from_slice(row);
38:     }
39:     raw
40: }
41: 
42: /// Wrap `raw` in a zlib stream built from stored deflate blocks.
43: fn zlib_stream(raw: &[u8]) -> Vec<u8> {
44:     let mut out = vec![0x78, 0x01];
45:     let blocks = raw.chunks(MAX_STORED_BLOCK).count();
46:     for (index, block) in raw.chunks(MAX_STORED_BLOCK).enumerate() {
47:         let last = index + 1 == blocks;
48:         out.push(u8::from(last));
49:         let length = block.len() as u16;
50:         out.extend_from_slice(&length.to_le_bytes());
51:         out.extend_from_slice(&(!length).to_le_bytes());
52:         out.extend_from_slice(block);
53:     }
54:     out.extend_from_slice(&adler32(raw).to_be_bytes());
55:     out
56: }
57: 
58: /// Compute the CRC-32 of the concatenated parts.
59: fn crc32(parts: &[&[u8]]) -> u32 {
60:     let mut crc = 0xffff_ffffu32;
61:     for part in parts {
62:         for &byte in *part {
63:             crc ^= byte as u32;
64:             for _ in 0..8 {
65:                 let mask = (crc & 1).wrapping_neg();
66:                 crc = (crc >> 1) ^ (0xedb8_8320 & mask);
67:             }
68:         }
69:     }
70:     !crc
71: }
72: 
73: /// Compute the Adler-32 checksum of the whole input.
74: fn adler32(data: &[u8]) -> u32 {
75:     let mut a = 1u32;
76:     let mut b = 0u32;
77:     for &byte in data {
78:         a = (a + byte as u32) % 65521;
79:         b = (b + a) % 65521;
80:     }
81:     (b << 16) | a
82: }
